=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md: holding registers for
// AW and W, READY computed from state only, one outstanding transaction per
// direction, SLVERR for unmapped (misaligned) addresses, 1-cycle latency.
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                      aclk,
    input  wire                      aresetn,
    input  wire [ADDR_WIDTH-1:0]     s_axil_awaddr,
    input  wire                      s_axil_awvalid,
    output wire                      s_axil_awready,
    input  wire [DATA_WIDTH-1:0]     s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0]   s_axil_wstrb,
    input  wire                      s_axil_wvalid,
    output wire                      s_axil_wready,
    output wire [1:0]                s_axil_bresp,
    output wire                      s_axil_bvalid,
    input  wire                      s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]     s_axil_araddr,
    input  wire                      s_axil_arvalid,
    output wire                      s_axil_arready,
    output wire [DATA_WIDTH-1:0]     s_axil_rdata,
    output wire [1:0]                s_axil_rresp,
    output wire                      s_axil_rvalid,
    input  wire                      s_axil_rready
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;
    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                   aw_held;
    reg                   w_held;
    reg                   bvalid_q;
    reg  [1:0]            bresp_q;
    reg                   rvalid_q;
    reg  [1:0]            rresp_q;
    reg  [DATA_WIDTH-1:0] rdata_q;

    // Holding registers: datapath, not reset (microarchitecture section 2).
    reg  [ADDR_WIDTH-1:0] aw_addr_q;
    reg  [DATA_WIDTH-1:0] w_data_q;
    reg  [STRB_WIDTH-1:0] w_strb_q;

    // Register file: four separate registers (microarchitecture section 3).
    reg  [DATA_WIDTH-1:0] reg0_q;
    reg  [DATA_WIDTH-1:0] reg1_q;
    reg  [DATA_WIDTH-1:0] reg2_q;
    reg  [DATA_WIDTH-1:0] reg3_q;

    // ------------------------------------------------------------------
    // Handshakes: READY depends on state only
    // ------------------------------------------------------------------
    wire awready_w = !aw_held && !bvalid_q;
    wire wready_w  = !w_held  && !bvalid_q;
    wire arready_w = !rvalid_q;

    wire aw_hs = s_axil_awvalid && awready_w;
    wire w_hs  = s_axil_wvalid  && wready_w;
    wire ar_hs = s_axil_arvalid && arready_w;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode (microarchitecture section 4)
    // ------------------------------------------------------------------
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_en     = do_write && wr_mapped;

    wire wr_en0 = wr_en && (wr_idx == 2'd0);
    wire wr_en1 = wr_en && (wr_idx == 2'd1);
    wire wr_en2 = wr_en && (wr_idx == 2'd2);
    wire wr_en3 = wr_en && (wr_idx == 2'd3);

    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    // ------------------------------------------------------------------
    // Byte-enable mask from wstrb
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] wmask;
    genvar gi;
    generate
        for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_wmask
            assign wmask[8*gi +: 8] = {8{wr_strb[gi]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] reg0_merged = (reg0_q & ~wmask) | (wr_data & wmask);
    wire [DATA_WIDTH-1:0] reg1_merged = (reg1_q & ~wmask) | (wr_data & wmask);
    wire [DATA_WIDTH-1:0] reg2_merged = (reg2_q & ~wmask) | (wr_data & wmask);
    wire [DATA_WIDTH-1:0] reg3_merged = (reg3_q & ~wmask) | (wr_data & wmask);

    // ------------------------------------------------------------------
    // Read mux
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] rd_word;
    always @(*) begin
        case (rd_idx)
            2'd0:    rd_word = reg0_q;
            2'd1:    rd_word = reg1_q;
            2'd2:    rd_word = reg2_q;
            2'd3:    rd_word = reg3_q;
            default: rd_word = {DATA_WIDTH{1'b0}};
        endcase
    end

    // ------------------------------------------------------------------
    // Write-side held flags
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held <= 1'b0;
            w_held  <= 1'b0;
        end else if (do_write) begin
            aw_held <= 1'b0;
            w_held  <= 1'b0;
        end else begin
            if (aw_hs) begin
                aw_held <= 1'b1;
            end
            if (w_hs) begin
                w_held <= 1'b1;
            end
        end
    end

    // Holding registers (load enable only, no reset by design)
    always @(posedge aclk) begin
        if (aw_hs && !do_write) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs && !do_write) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Register file
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            reg0_q <= {DATA_WIDTH{1'b0}};
            reg1_q <= {DATA_WIDTH{1'b0}};
            reg2_q <= {DATA_WIDTH{1'b0}};
            reg3_q <= {DATA_WIDTH{1'b0}};
        end else begin
            if (wr_en0) begin
                reg0_q <= reg0_merged;
            end
            if (wr_en1) begin
                reg1_q <= reg1_merged;
            end
            if (wr_en2) begin
                reg2_q <= reg2_merged;
            end
            if (wr_en3) begin
                reg3_q <= reg3_merged;
            end
        end
    end

    // ------------------------------------------------------------------
    // B channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            bvalid_q <= 1'b0;
            bresp_q  <= RESP_OKAY;
        end else if (do_write) begin
            bvalid_q <= 1'b1;
            bresp_q  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
        end else if (bvalid_q && s_axil_bready) begin
            bvalid_q <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // R channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
        end else if (ar_hs) begin
            rvalid_q <= 1'b1;
            rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
            rdata_q  <= rd_mapped ? rd_word : {DATA_WIDTH{1'b0}};
        end else if (rvalid_q && s_axil_rready) begin
            rvalid_q <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = awready_w;
    assign s_axil_wready  = wready_w;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready_w;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (microarchitecture section 7)
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) begin
        f_past_valid <= 1'b1;
    end

    // Reset is active on the first cycle; manager VALIDs low during reset.
    always @(*) begin
        if (!f_past_valid) begin
            assume(!aresetn);
        end
        if (!aresetn) begin
            assume(!s_axil_awvalid);
            assume(!s_axil_wvalid);
            assume(!s_axil_arvalid);
        end
    end

    // Manager holds VALID and payload until READY.
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid) && !$past(s_axil_awready)) begin
                assume(s_axil_awvalid);
                assume(s_axil_awaddr == $past(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid) && !$past(s_axil_wready)) begin
                assume(s_axil_wvalid);
                assume(s_axil_wdata == $past(s_axil_wdata));
                assume(s_axil_wstrb == $past(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid) && !$past(s_axil_arready)) begin
                assume(s_axil_arvalid);
                assume(s_axil_araddr == $past(s_axil_araddr));
            end
        end
    end

    // State invariants.
    always @(*) begin
        if (f_past_valid) begin
            assert(!(aw_held && w_held));
            if (bvalid_q) begin
                assert(!aw_held && !w_held);
            end
            assert((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
            if (rresp_q == RESP_SLVERR) begin
                assert(rdata_q == {DATA_WIDTH{1'b0}});
            end
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid) begin
            // Responses low after reset.
            if (!$past(aresetn)) begin
                assert(!s_axil_bvalid);
                assert(!s_axil_rvalid);
            end
            if ($past(aresetn)) begin
                // B and R hold, with stable payload, until taken.
                if ($past(s_axil_bvalid) && !$past(s_axil_bready)) begin
                    assert(s_axil_bvalid);
                    assert(s_axil_bresp == $past(s_axil_bresp));
                end
                if ($past(s_axil_rvalid) && !$past(s_axil_rready)) begin
                    assert(s_axil_rvalid);
                    assert(s_axil_rresp == $past(s_axil_rresp));
                    assert(s_axil_rdata == $past(s_axil_rdata));
                end
                // A response appears only after an accepted request.
                if (!$past(s_axil_bvalid) && s_axil_bvalid) begin
                    assert($past(do_write));
                end
                if (!$past(s_axil_rvalid) && s_axil_rvalid) begin
                    assert($past(ar_hs));
                end
                // Response codes follow the address policy.
                if ($past(do_write)) begin
                    assert(s_axil_bvalid);
                    assert(s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
                end
                if ($past(ar_hs)) begin
                    assert(s_axil_rvalid);
                    assert(s_axil_rresp == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR));
                    assert(s_axil_rdata == ($past(rd_mapped) ? $past(rd_word) : {DATA_WIDTH{1'b0}}));
                end
            end
        end
    end

    // Covers: completed write and read, both orderings of AW and W, SLVERR.
    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover(s_axil_bvalid && s_axil_bready);
            cover(s_axil_rvalid && s_axil_rready);
            cover(aw_held && w_hs);
            cover(w_held && aw_hs);
            cover(s_axil_rvalid && (s_axil_rresp == RESP_SLVERR));
        end
    end
`endif

endmodule
=== END FILE ===
