// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven just after the falling edge; outputs are sampled at the
// falling edge, so a handshake at the next rising edge happens exactly when
// VALID (driven now) and READY (a function of DUT state) are both high.

`define TB_CHECK(cond, msg) \
    begin \
        if (cond) begin \
            passed = passed + 1; \
        end else begin \
            failed = failed + 1; \
            $error msg; \
        end \
    end

module axi4_lite_regs_tb;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg         aclk = 1'b0;
    reg         aresetn;
    reg  [3:0]  awaddr;
    reg         awvalid;
    wire        awready;
    reg  [31:0] wdata;
    reg  [3:0]  wstrb;
    reg         wvalid;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    reg         bready;
    reg  [3:0]  araddr;
    reg         arvalid;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;
    reg         rready;

    integer passed;
    integer failed;
    integer last_req_cycles;
    reg [31:0] model [0:3];
    reg [8*64-1:0] nonce;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready)
    );

    always #5 aclk = ~aclk;

    // ------------------------------------------------------------------
    // Reference model helpers
    // ------------------------------------------------------------------
    function [31:0] merge32(input [31:0] old_v, input [31:0] new_v, input [3:0] strb);
        begin
            merge32 = { (strb[3] ? new_v[31:24] : old_v[31:24]),
                        (strb[2] ? new_v[23:16] : old_v[23:16]),
                        (strb[1] ? new_v[15:8]  : old_v[15:8]),
                        (strb[0] ? new_v[7:0]   : old_v[7:0]) };
        end
    endfunction

    function [1:0] exp_resp_of(input [3:0] addr);
        begin
            exp_resp_of = (addr[1:0] == 2'b00) ? OKAY : SLVERR;
        end
    endfunction

    // ------------------------------------------------------------------
    // One write. aw_dly / w_dly: cycles before raising AWVALID / WVALID.
    // b_dly: cycles BREADY stays low after BVALID; negative means BREADY
    // is high from the start.
    // ------------------------------------------------------------------
    task do_write(input [3:0] addr, input [31:0] data, input [3:0] strb,
                  input integer aw_dly, input integer w_dly, input integer b_dly);
        reg        aw_done;
        reg        w_done;
        reg        aw_fire;
        reg        w_fire;
        reg [1:0]  exp_resp;
        reg [1:0]  held_resp;
        integer    cyc;
        integer    lat;
        begin
            exp_resp = exp_resp_of(addr);
            aw_done  = 1'b0;
            w_done   = 1'b0;
            cyc      = 0;
            bready   = (b_dly < 0);
            while (!(aw_done && w_done) && (cyc < 50)) begin
                awaddr  = addr;
                awvalid = !aw_done && (cyc >= aw_dly);
                wdata   = data;
                wstrb   = strb;
                wvalid  = !w_done && (cyc >= w_dly);
                `TB_CHECK(!bvalid, ("write 0x%h: BVALID high before AW and W were both accepted", addr))
                if (aw_done) begin
                    `TB_CHECK(!awready, ("write 0x%h: AWREADY high while the address is held", addr))
                end else begin
                    `TB_CHECK(awready, ("write 0x%h: AWREADY low while no write is pending", addr))
                end
                if (w_done) begin
                    `TB_CHECK(!wready, ("write 0x%h: WREADY high while the data is held", addr))
                end else begin
                    `TB_CHECK(wready, ("write 0x%h: WREADY low while no write is pending", addr))
                end
                aw_fire = awvalid && awready;
                w_fire  = wvalid && wready;
                @(negedge aclk);
                if (aw_fire) aw_done = 1'b1;
                if (w_fire)  w_done  = 1'b1;
                cyc = cyc + 1;
            end
            awvalid = 1'b0;
            wvalid  = 1'b0;
            last_req_cycles = cyc;
            `TB_CHECK(aw_done && w_done, ("write 0x%h: request not accepted within 50 cycles", addr))

            lat = 1;
            while (!bvalid && (lat < 4)) begin
                @(negedge aclk);
                lat = lat + 1;
            end
            `TB_CHECK(bvalid, ("write 0x%h: no write response", addr))
            `TB_CHECK(lat <= 2, ("write 0x%h: latency %0d exceeds the 2-cycle bound", addr, lat))
            `TB_CHECK(lat == 1, ("write 0x%h: latency %0d, design latency is 1", addr, lat))
            `TB_CHECK(bresp == exp_resp, ("write 0x%h: BRESP %b, expected %b", addr, bresp, exp_resp))
            `TB_CHECK(!awready && !wready, ("write 0x%h: AWREADY/WREADY high while BVALID pending", addr))
            held_resp = bresp;

            cyc = 0;
            while (cyc < b_dly) begin
                bready = 1'b0;
                @(negedge aclk);
                `TB_CHECK(bvalid, ("write 0x%h: BVALID dropped under back-pressure", addr))
                `TB_CHECK(bresp == held_resp, ("write 0x%h: BRESP changed under back-pressure", addr))
                `TB_CHECK(!awready && !wready, ("write 0x%h: new write accepted while B stalled", addr))
                cyc = cyc + 1;
            end
            bready = 1'b1;
            @(negedge aclk);
            bready = 1'b0;
            `TB_CHECK(!bvalid, ("write 0x%h: BVALID still high after the response was taken", addr))

            if (exp_resp == OKAY) begin
                model[addr[3:2]] = merge32(model[addr[3:2]], data, strb);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // One read. ar_dly: cycles before ARVALID. r_dly: cycles RREADY stays
    // low after RVALID; negative means RREADY is high from the start.
    // ------------------------------------------------------------------
    task do_read(input [3:0] addr, input integer ar_dly, input integer r_dly);
        reg        ar_done;
        reg        ar_fire;
        reg [1:0]  exp_resp;
        reg [31:0] exp_data;
        reg [1:0]  held_resp;
        reg [31:0] held_data;
        integer    cyc;
        integer    lat;
        begin
            exp_resp = exp_resp_of(addr);
            exp_data = (exp_resp == OKAY) ? model[addr[3:2]] : 32'h0000_0000;
            ar_done  = 1'b0;
            cyc      = 0;
            rready   = (r_dly < 0);
            while (!ar_done && (cyc < 50)) begin
                araddr  = addr;
                arvalid = (cyc >= ar_dly);
                `TB_CHECK(!rvalid, ("read 0x%h: RVALID high before AR was accepted", addr))
                `TB_CHECK(arready, ("read 0x%h: ARREADY low while no read is pending", addr))
                ar_fire = arvalid && arready;
                @(negedge aclk);
                if (ar_fire) ar_done = 1'b1;
                cyc = cyc + 1;
            end
            arvalid = 1'b0;
            last_req_cycles = cyc;
            `TB_CHECK(ar_done, ("read 0x%h: request not accepted within 50 cycles", addr))

            lat = 1;
            while (!rvalid && (lat < 4)) begin
                @(negedge aclk);
                lat = lat + 1;
            end
            `TB_CHECK(rvalid, ("read 0x%h: no read response", addr))
            `TB_CHECK(lat <= 2, ("read 0x%h: latency %0d exceeds the 2-cycle bound", addr, lat))
            `TB_CHECK(lat == 1, ("read 0x%h: latency %0d, design latency is 1", addr, lat))
            `TB_CHECK(rresp == exp_resp, ("read 0x%h: RRESP %b, expected %b", addr, rresp, exp_resp))
            `TB_CHECK(rdata == exp_data, ("read 0x%h: RDATA 0x%h, expected 0x%h", addr, rdata, exp_data))
            `TB_CHECK(!arready, ("read 0x%h: ARREADY high while RVALID pending", addr))
            held_resp = rresp;
            held_data = rdata;

            cyc = 0;
            while (cyc < r_dly) begin
                rready = 1'b0;
                @(negedge aclk);
                `TB_CHECK(rvalid, ("read 0x%h: RVALID dropped under back-pressure", addr))
                `TB_CHECK(rresp == held_resp, ("read 0x%h: RRESP changed under back-pressure", addr))
                `TB_CHECK(rdata == held_data, ("read 0x%h: RDATA changed under back-pressure", addr))
                `TB_CHECK(!arready, ("read 0x%h: new read accepted while R stalled", addr))
                cyc = cyc + 1;
            end
            rready = 1'b1;
            @(negedge aclk);
            rready = 1'b0;
            `TB_CHECK(!rvalid, ("read 0x%h: RVALID still high after the response was taken", addr))
        end
    endtask

    // ------------------------------------------------------------------
    // AW, W and AR all presented on the same clock.
    // ------------------------------------------------------------------
    task do_write_read_same_cycle(input [3:0] waddr, input [31:0] data, input [3:0] strb,
                                  input [3:0] raddr, input integer hold);
        reg [1:0]  exp_bresp;
        reg [1:0]  exp_rresp;
        reg [31:0] exp_rdata;
        integer    cyc;
        begin
            exp_bresp = exp_resp_of(waddr);
            exp_rresp = exp_resp_of(raddr);
            exp_rdata = (exp_rresp == OKAY) ? model[raddr[3:2]] : 32'h0000_0000;
            `TB_CHECK(awready && wready && arready, ("same-cycle: READY not high while idle"))
            awaddr  = waddr;
            awvalid = 1'b1;
            wdata   = data;
            wstrb   = strb;
            wvalid  = 1'b1;
            araddr  = raddr;
            arvalid = 1'b1;
            bready  = 1'b0;
            rready  = 1'b0;
            @(negedge aclk);
            awvalid = 1'b0;
            wvalid  = 1'b0;
            arvalid = 1'b0;
            `TB_CHECK(bvalid && rvalid, ("same-cycle: BVALID/RVALID not both high one cycle later"))
            `TB_CHECK(bresp == exp_bresp, ("same-cycle: BRESP %b, expected %b", bresp, exp_bresp))
            `TB_CHECK(rresp == exp_rresp, ("same-cycle: RRESP %b, expected %b", rresp, exp_rresp))
            `TB_CHECK(rdata == exp_rdata, ("same-cycle: RDATA 0x%h, expected 0x%h", rdata, exp_rdata))
            cyc = 0;
            while (cyc < hold) begin
                @(negedge aclk);
                `TB_CHECK(bvalid && rvalid, ("same-cycle: a response dropped under back-pressure"))
                `TB_CHECK(bresp == exp_bresp, ("same-cycle: BRESP changed under back-pressure"))
                `TB_CHECK(rresp == exp_rresp, ("same-cycle: RRESP changed under back-pressure"))
                `TB_CHECK(rdata == exp_rdata, ("same-cycle: RDATA changed under back-pressure"))
                cyc = cyc + 1;
            end
            bready = 1'b1;
            rready = 1'b1;
            @(negedge aclk);
            bready = 1'b0;
            rready = 1'b0;
            `TB_CHECK(!bvalid && !rvalid, ("same-cycle: responses still high after being taken"))
            if (exp_bresp == OKAY) begin
                model[waddr[3:2]] = merge32(model[waddr[3:2]], data, strb);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    // ------------------------------------------------------------------
    initial begin
        #200000;
        $error("watchdog: testbench did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

    // ------------------------------------------------------------------
    // Directed sequence
    // ------------------------------------------------------------------
    initial begin
        passed = 0;
        failed = 0;
        last_req_cycles = 0;
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end

        aresetn = 1'b0;
        awaddr  = 4'h0;
        awvalid = 1'b0;
        wdata   = 32'h0000_0000;
        wstrb   = 4'h0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = 4'h0;
        arvalid = 1'b0;
        rready  = 1'b0;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;

        // ---------------- Reset ----------------
        repeat (3) @(negedge aclk);
        `TB_CHECK(!bvalid && !rvalid, ("BVALID/RVALID high during reset"))
        aresetn = 1'b1;
        `TB_CHECK(awready && wready && arready, ("READY not high after reset"))
        @(negedge aclk);
        `TB_CHECK(!bvalid && !rvalid, ("BVALID/RVALID high after reset with no request"))

        // ---------------- Reset values ----------------
        do_read(4'h0, 0, 0);
        do_read(4'h4, 0, 0);
        do_read(4'h8, 0, 0);
        do_read(4'hC, 0, 0);

        // ---------------- Write then read every register, AW/W orders ----------------
        do_write(4'h0, 32'h1122_3344, 4'hF, 0, 0, 0);   // AW and W together
        do_write(4'h4, 32'hA5A5_0001, 4'hF, 0, 3, 0);   // AW before W
        do_write(4'h8, 32'hDEAD_BEEF, 4'hF, 3, 0, 0);   // W before AW
        do_write(4'hC, 32'h0BAD_F00D, 4'hF, 1, 1, -1);  // together after a gap, BREADY early
        do_read(4'h0, 0, 0);
        do_read(4'h4, 2, 0);
        do_read(4'h8, 0, -1);
        do_read(4'hC, 0, 0);

        // ---------------- WSTRB partial and empty writes ----------------
        do_write(4'h0, 32'hAABB_CCDD, 4'b0101, 0, 0, 0);
        do_read(4'h0, 0, 0);
        do_write(4'h4, 32'h7700_0000, 4'b1000, 0, 1, 0);
        do_read(4'h4, 0, 0);
        do_write(4'h8, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);  // no byte enabled: OKAY, no change
        do_read(4'h8, 0, 0);
        do_write(4'hC, 32'h1234_5678, 4'b0011, 2, 0, 0);
        do_read(4'hC, 0, 0);
        `TB_CHECK(model[0] == 32'h11BB_33DD, ("model REG0 0x%h after strobes", model[0]))
        `TB_CHECK(model[1] == 32'h77A5_0001, ("model REG1 0x%h after strobes", model[1]))
        `TB_CHECK(model[2] == 32'hDEAD_BEEF, ("model REG2 0x%h after strobes", model[2]))
        `TB_CHECK(model[3] == 32'h0BAD_5678, ("model REG3 0x%h after strobes", model[3]))

        // ---------------- B and R back-pressure ----------------
        do_write(4'h8, 32'hCAFE_0008, 4'hF, 0, 0, 5);
        do_read(4'h8, 0, 6);
        do_write(4'h4, 32'h0101_0101, 4'b0110, 2, 0, 3);
        do_read(4'h4, 1, 4);

        // ---------------- SLVERR policy ----------------
        do_write(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
        do_write(4'hE, 32'hFFFF_FFFF, 4'hF, 2, 0, 2);
        do_write(4'h3, 32'hFFFF_FFFF, 4'hF, 0, 2, 0);
        do_read(4'h4, 0, 0);
        do_read(4'hC, 0, 0);
        do_read(4'h0, 0, 0);
        do_read(4'h5, 0, 0);
        do_read(4'hE, 1, 3);
        do_read(4'h1, 0, -1);

        // ---------------- Back-to-back transactions ----------------
        do_write(4'h0, 32'h0000_0001, 4'hF, 0, 0, 0);
        do_write(4'h4, 32'h0000_0002, 4'hF, 0, 0, 0);
        `TB_CHECK(last_req_cycles == 1, ("back-to-back write not accepted in the next cycle"))
        do_write(4'h8, 32'h0000_0003, 4'hF, 0, 0, 0);
        `TB_CHECK(last_req_cycles == 1, ("back-to-back write not accepted in the next cycle"))
        do_write(4'hC, 32'h0000_0004, 4'hF, 0, 0, 0);
        `TB_CHECK(last_req_cycles == 1, ("back-to-back write not accepted in the next cycle"))
        do_read(4'h0, 0, 0);
        do_read(4'h4, 0, 0);
        `TB_CHECK(last_req_cycles == 1, ("back-to-back read not accepted in the next cycle"))
        do_read(4'h8, 0, 0);
        `TB_CHECK(last_req_cycles == 1, ("back-to-back read not accepted in the next cycle"))
        do_read(4'hC, 0, 0);
        `TB_CHECK(last_req_cycles == 1, ("back-to-back read not accepted in the next cycle"))

        // ---------------- Read and write on the same clock ----------------
        do_write_read_same_cycle(4'h0, 32'h5555_AAAA, 4'hF, 4'h4, 0);
        do_write_read_same_cycle(4'h8, 32'h1357_9BDF, 4'b1100, 4'h0, 3);
        do_write_read_same_cycle(4'h6, 32'hFFFF_FFFF, 4'hF, 4'hD, 1);
        do_read(4'h0, 0, 0);
        do_read(4'h8, 0, 0);
        do_read(4'h4, 0, 0);

        // ---------------- Reset during traffic ----------------
        awaddr  = 4'h8;
        awvalid = 1'b1;
        wvalid  = 1'b0;
        araddr  = 4'h0;
        arvalid = 1'b1;
        rready  = 1'b0;
        bready  = 1'b0;
        `TB_CHECK(awready && arready, ("reset test: READY low before AW/AR"))
        @(negedge aclk);
        awvalid = 1'b0;
        arvalid = 1'b0;
        `TB_CHECK(rvalid, ("reset test: read response not pending"))
        `TB_CHECK(!awready, ("reset test: address not held"))
        `TB_CHECK(!bvalid, ("reset test: BVALID high with only AW accepted"))
        aresetn = 1'b0;
        @(negedge aclk);
        `TB_CHECK(!bvalid && !rvalid, ("reset test: responses not cleared by reset"))
        @(negedge aclk);
        aresetn = 1'b1;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;
        `TB_CHECK(awready && wready && arready, ("reset test: READY not high after reset"))
        // W alone must not pair with the discarded AW.
        wdata  = 32'h1234_5678;
        wstrb  = 4'hF;
        wvalid = 1'b1;
        @(negedge aclk);
        wvalid = 1'b0;
        `TB_CHECK(!wready, ("reset test: write data not held"))
        `TB_CHECK(awready, ("reset test: AWREADY low with no address held"))
        `TB_CHECK(!bvalid, ("reset test: write completed with a discarded address"))
        repeat (3) begin
            @(negedge aclk);
            `TB_CHECK(!bvalid, ("reset test: spurious BVALID after reset"))
        end
        // A new AW completes the write with the held data.
        awaddr  = 4'h4;
        awvalid = 1'b1;
        @(negedge aclk);
        awvalid = 1'b0;
        `TB_CHECK(bvalid, ("reset test: write not completed by the new AW"))
        `TB_CHECK(bresp == OKAY, ("reset test: BRESP %b, expected OKAY", bresp))
        bready = 1'b1;
        @(negedge aclk);
        bready = 1'b0;
        `TB_CHECK(!bvalid, ("reset test: BVALID still high after the response was taken"))
        model[1] = 32'h1234_5678;
        do_read(4'h0, 0, 0);
        do_read(4'h4, 0, 0);
        do_read(4'h8, 0, 0);
        do_read(4'hC, 0, 0);

        // ---------------- Verdict ----------------
        repeat (2) @(negedge aclk);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
